package com.acme.core.application.rbac;

import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;

import java.time.LocalDateTime;
import java.util.List;

/**
 * User management response (generated by engineering-platform 0.1.0).
 * Never exposes passwordHash or any password material.
 */
public record UserResponse(
        @JsonSerialize(using = ToStringSerializer.class)
        Long id,
        String username,
        Boolean enabled,
        Long departmentId,
        @JsonSerialize(contentUsing = ToStringSerializer.class)
        List<Long> roleIds,
        LocalDateTime createdAt) {

    public static UserResponse of(Long id, String username, Boolean enabled,
                                  Long departmentId, List<Long> roleIds, LocalDateTime createdAt) {
        return new UserResponse(id, username, enabled, departmentId, roleIds, createdAt);
    }
}
